// Seed fixture: `seeded_movies_search` — a small deterministic `sample.movies` collection
// plus an Atlas Search index, for the mongodb-search-and-ai functional task (Tier 2).
// Requires the mongodb/mongodb-atlas-local image (bundles the search process); plain mongo:8
// does NOT support $search / createSearchIndex.
//
// Applied per-case by solvers/seed_db.py. Deterministic membership so functional_db can
// compare: exactly two plots contain the token "robot" (Metro, Nexus); the others don't.
const sample = db.getSiblingDB('sample')

sample.movies.drop()
sample.movies.insertMany([
  { title: 'Metro', genre: 'comedy', plot: 'a lonely robot finds friendship in a big city' },
  { title: 'Nexus', genre: 'scifi', plot: 'a robot uprising threatens the megacity' },
  { title: 'Harbor', genre: 'drama', plot: 'a fisherman battles a relentless winter storm' },
  { title: 'Circuit', genre: 'comedy', plot: 'two hackers pull off a daring bank heist' },
])

// Create an Atlas Search index and WAIT until it is queryable. Two async hazards on
// mongodb-atlas-local:
//   1. mongot (the Search Index Management service) starts AFTER mongod, and the compose
//      healthcheck only gates on mongod — so createSearchIndex can transiently fail with
//      "Error connecting to Search Index Management service". Retry until it accepts.
//   2. createSearchIndex itself is async — the index isn't queryable immediately.
// English analyzer so the query is robust to stemming (e.g. "robots" matches "robot") —
// otherwise full-text membership would hinge on the agent guessing singular vs. plural.
const indexDef = {
  mappings: { dynamic: false, fields: { plot: { type: 'string', analyzer: 'lucene.english' } } },
}

let created = false
for (let i = 0; i < 60 && !created; i++) {
  try {
    sample.movies.createSearchIndex('default', indexDef)
    created = true
  } catch (e) {
    if (String(e).indexOf('already exists') >= 0) {
      created = true
    } else {
      sleep(2000) // mongot not ready yet
    }
  }
}
if (!created) {
  throw new Error('createSearchIndex failed: Search Index Management service (mongot) not ready')
}

let ready = false
for (let i = 0; i < 90; i++) {
  try {
    const idx = sample.movies.getSearchIndexes('default')
    if (idx.length && (idx[0].queryable === true || idx[0].status === 'READY')) {
      ready = true
      break
    }
  } catch (e) {
    /* transient while the service settles */
  }
  sleep(1000)
}
print('seeded sample.movies=' + sample.movies.countDocuments() + ' searchIndexReady=' + ready)
if (!ready) {
  throw new Error('Atlas Search index "default" did not become queryable in time')
}

// Seed fixture: `seeded_movies_autoembed` — a small deterministic `sample.movies` collection
// for the Automated Embedding functional task.
//
// Requires an Atlas CLOUD cluster: `autoEmbed` index fields are generated by MongoDB's hosted
// Voyage AI inference, which neither plain mongo:8 nor mongodb/mongodb-atlas-local provides.
//
// Unlike `seeded_movies_search`, this fixture deliberately does NOT create the search index —
// building the `autoEmbed` index is the behaviour under test, so the agent creates it. The
// drop() below is what keeps that repeatable on a persistent cluster: dropping a collection
// also drops the search indexes defined on it, so a rerun starts from zero indexes instead of
// accumulating them against the tier's search-index cap.
//
// Applied per-case by solvers/seed_db.py. Plots are chosen so the semantic target is separable
// WITHOUT shared vocabulary: nothing contains "growing up" or "coming of age", so a lexical
// query cannot pass this case — only real embeddings rank Ninth Grade and Summer of Eleven
// above the other four.
const sample = db.getSiblingDB('sample')

sample.movies.drop()
sample.movies.insertMany([
  {
    title: 'Ninth Grade',
    genres: ['Drama'],
    plot: 'a shy teenager navigates his first year of high school and slowly finds his voice',
  },
  {
    title: 'Summer of Eleven',
    genres: ['Drama'],
    plot: 'a girl spends the long summer before secondary school learning who she wants to become',
  },
  {
    title: 'Cold Front',
    genres: ['Thriller'],
    plot: 'a submarine crew races to stop a nuclear launch in the north atlantic',
  },
  {
    title: 'The Proof',
    genres: ['Drama'],
    plot: 'a mathematician spends a decade chasing a single unsolved theorem',
  },
  {
    title: 'Saffron',
    genres: ['Comedy'],
    plot: 'a chef rebuilds her restaurant after a fire destroys the kitchen',
  },
  {
    title: 'Deep Field',
    genres: ['Sci-Fi'],
    plot: 'an astronomer detects a signal from beyond the observable universe',
  },
])

const n = sample.movies.countDocuments()
print('seeded sample.movies=' + n + ' searchIndexes=agent-created')
if (n !== 6) {
  throw new Error('expected 6 seeded documents, got ' + n)
}

